int sum_positive(const int values[], size_t count)
{
    int total = 0;
    for (size_t i = 0; i < count; i++) {
        if (values[i] <= 0) continue;
        total += values[i];
    }
    return total;
}

int main(void)
{
    int values[] = {3, -2, 7, 0, 5};
    size_t count = sizeof(values) / sizeof(values[0]);
    printf("sum=%d\n", sum_positive(values, count));
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

int main(void)
{
    FILE *file = tmpfile();
    if (file == NULL) return EXIT_FAILURE;
    if (fprintf(file, "%d %d %d\n", 2, 4, 6) < 0) {
        fclose(file);
        return EXIT_FAILURE;
    }
    rewind(file);
    int value = 0, total = 0;
    while (fscanf(file, "%d", &value) == 1) {
        total += value;
    }
    int failed = ferror(file);
    if (fclose(file) != 0) failed = 1;
    if (failed) return EXIT_FAILURE;
    printf("total=%d\n", total);
    return EXIT_SUCCESS;
}

#include <stddef.h>
#include <stdio.h>

typedef struct {
    const char *name;
    int score;
} Item;

int read_score(const Item *item)
{
    return item->score;
}

int sum_items(const Item items[], size_t count,
              int (*read)(const Item *))
{
    int total = 0;
    for (size_t i = 0; i < count; i++) {
        total += read(&items[i]);
    }
    return total;
}

int main(void)
{
    Item items[] = {{"A", 4}, {"B", 9}};
    size_t count = sizeof(items) / sizeof(items[0]);
    printf("score=%d\n", sum_items(items, count, read_score));
    return 0;
}

