void make_upper(char text[])
{
    for (size_t i = 0; text[i] != '\0'; i++) {
        text[i] = (char)toupper((unsigned char)text[i]);
    }
}

int main(void)
{
    char text[32] = "hello 123";
    make_upper(text);
    printf("%s (%zu)\n", text, strlen(text));
    return 0;
}

