struct Pair {
    int first;
    int second;
};

int sum_arguments(int count, ...)
{
    va_list args;
    va_start(args, count);
    int total = 0;
    for (int i = 0; i < count; i++) {
        total += va_arg(args, int);
    }
    va_end(args);
    return total;
}

int main(void)
{
    size_t offset = offsetof(struct Pair, second);
    printf("sum=%d, layout=%d\n", sum_arguments(3, 2, 4, 6), offset > 0);
    return 0;
}

